import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"復","description":"焦氏易林注 - 復","frontmatter":{"title":"復","description":"焦氏易林注 - 復"},"headers":[],"relativePath":"classics/jiaoyilin/024.md","filePath":"classics/jiaoyilin/024.md"}'),l={name:"classics/jiaoyilin/024.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="復" tabindex="-1">復 <a class="header-anchor" href="#復" aria-label="Permalink to “復”">​</a></h1><h3 id="復-1" tabindex="-1">復 <a class="header-anchor" href="#復-1" aria-label="Permalink to “復”">​</a></h3><h3 id="復之乾" tabindex="-1">復之乾 <a class="header-anchor" href="#復之乾" aria-label="Permalink to “復之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>任武負力，東徵不伏。蹈泥履塗，雄師敗覆。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦&quot;復&quot;象。震為武、為東徵、為蹈，履坤為水、為泥塗、為師，坤喪故敗覆。○第三句汲古作&quot;陷履泥塗&quot;，宋本作&quot;陷泥履塗&quot;，茲依元本。</p><h3 id="復之坤" tabindex="-1">復之坤 <a class="header-anchor" href="#復之坤" aria-label="Permalink to “復之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>義不勝情，以欲自營。覬利危躬，折角摧頸。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>坤為義、為情慾、為躬，坤死故危躬。艮為角、為頸，《復》下震為覆艮，艮覆故曰折角摧頸。此亦全用遇卦象。○覬，元本作為，依宋木、汲古。躬，宋元本作寵，從汲古。</p><h3 id="復之屯" tabindex="-1">復之屯 <a class="header-anchor" href="#復之屯" aria-label="Permalink to “復之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>懸貆素飡，食非其任。失輿剝廬，休坐徙居，室家何憂。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>艮貆，艮陽在上故曰懸貆。震為口、為白，故曰素飡。《詩魏風》：&quot;胡瞻爾庭有懸貆兮，彼君子兮，不素餐兮&quot;，飡，即餐也。震為食、為輿，坤喪故失輿。艮為廬，坎破故剝廬。艮為坐、為居，震行故徙居。艮為室家，坎為憂，震樂故無憂。○貆，宋元本、汲古本作狟，依湖北局本，與詩合。飡，元本作餐，依宋本、汲古。按：《說文》狟，犬行也。《廣韻》狟與貆通。然三本皆作狟，是焦詩本作狟。</p><h3 id="復之蒙" tabindex="-1">復之蒙 <a class="header-anchor" href="#復之蒙" aria-label="Permalink to “復之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>鷂鴟娶婦，深目窈身。折腰不媚，與伯相背。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮為鷂鴟。震為娶，坤為婦，互大離故曰深目。坤為身、為黑，故曰窈身。坎為腰、為折，震為武、為健，故曰不媚。震為伯，艮為背。○鶹●鶹亦●屬，宋元作鷂，依汲古。</p><h3 id="復之需" tabindex="-1">復之需 <a class="header-anchor" href="#復之需" aria-label="Permalink to “復之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>東風解凍，河川流通。西門子產，升擢有功。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>坎為凍，離為東，故曰東風解凍。坎為河川，位西，乾為門，故曰西門。魏西門豹、鄭子產皆循吏，乾為貴，故曰升擢有功。</p><h3 id="復之訟" tabindex="-1">復之訟 <a class="header-anchor" href="#復之訟" aria-label="Permalink to “復之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>三足俱行，傾危善僵。六指不便，慁累弟兄。樹柱閡車，失其正當。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《鹹》。 ○慁累，汲古作累慁，宋元作恩累，茲依《賁》之《鹹》校。</p><h3 id="復之師" tabindex="-1">復之師 <a class="header-anchor" href="#復之師" aria-label="Permalink to “復之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>京庾積倉，黍稷以興。極行疾至，以饜飽食。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坤為倉庾、為積，震為黍稷、為行、為亟，為疾、為食，坎為飽。○宋元本極上多己字，飽下無食字，非，依汲古。惟汲古行作其，亦非。《詩小雅甫田》篇：&quot;曾孫之庾，如坻如京；乃求千斯倉，黍稷稻梁。&quot;極當為亟。</p><h3 id="復之比" tabindex="-1">復之比 <a class="header-anchor" href="#復之比" aria-label="Permalink to “復之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>南山之蹊，真人所在。德配唐虞，天命為子。保佑歆享，身受大慶。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《解》。</p><h3 id="復之小畜" tabindex="-1">復之小畜 <a class="header-anchor" href="#復之小畜" aria-label="Permalink to “復之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>車馳人趨，捲甲相仇。齊魯寇戰，敗於犬邱。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《兌》。</p><h3 id="復之履" tabindex="-1">復之履 <a class="header-anchor" href="#復之履" aria-label="Permalink to “復之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>十五許室，柔順有德。霜降既嫁，文以為合。先王日至，不利出域。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>兌數十，巽卦數五，故曰十五。伏坎為室，震為言，故曰許室，言以女字人也。坤為柔順，坎為霜，震為嫁，坤為文，坎為合，詩文定厥祥是也。震為王，《謙》三至上復為日至。丁晏雲：《周禮媒氏》疏王肅引《韓詩傳》：&quot;古者霜降，逆女冰泮殺止&quot;，《荀子大略篇》說同。又引《家語》雲&quot;霜降而婦功成，嫁娶者行焉；冰泮而農業起，昏禮殺於此&quot;，茲雲&quot;霜降既嫁&quot;，是焦氏說與《荀子》、《韓詩》說合，由是證《詩》&quot;迨冰未泮&quot;，言及冰未泮而歸妻，若已泮則殺止。《鄭箋》謂正月中冰未泮，至二月可以昏者，非也。○既，汲古作歸，文作夫，均依宋元本。《復》象雲&quot;先王以至日閉關，商旅不行，後不省方&quot;，故雲不利出域。</p><h3 id="復之泰" tabindex="-1">復之泰 <a class="header-anchor" href="#復之泰" aria-label="Permalink to “復之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>任力劣薄，遠託邦國。輔車不強，為癰所傷。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>震健故曰任力。坤為邦國、為車，坤柔故曰不強。伏艮為節、為癰，兌為傷。○託，汲古作託，強作僵，依宋元本。</p><h3 id="復之否" tabindex="-1">復之否 <a class="header-anchor" href="#復之否" aria-label="Permalink to “復之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>千歲舊室，將有困急。荷糧負囊，出門直北。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>坤為千歲，乾為舊，艮為室，巽為隕落，故曰困急。艮為荷、為負，巽為糧，坤為囊、為門、為北，故曰出門直北。</p><h3 id="復之同人" tabindex="-1">復之同人 <a class="header-anchor" href="#復之同人" aria-label="Permalink to “復之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>兇憂災殃，日益章明。禍不可救，三卻夷傷。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>詳《噬嗑》之《剝》。○首句依《噬嗑》之《剝》校改，各本皆作&quot;惡災殆盈&quot;，惟三卻彼取象於退，此以巽隙取象，離數三，故曰三卻。</p><h3 id="復之大有" tabindex="-1">復之大有 <a class="header-anchor" href="#復之大有" aria-label="Permalink to “復之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>冠危戴患，身驚不安。與福馳逐，兇來入門。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。坎為危患，艮為冠戴、為身，坎陷故不安。艮為門，坤為兇。○戴，汲古作載，依宋元本。</p><h3 id="復之謙" tabindex="-1">復之謙 <a class="header-anchor" href="#復之謙" aria-label="Permalink to “復之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>虎狼並處，不可以仕。忠謀輔政，禍必及己。退隱深山，身乃不殆。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>艮為處，狼正覆艮故曰並處。艮為仕，坎險故不可仕。坎為忠、為謀，坤為禍、為己，艮為山，坎為隱，坤為身、為殆，震樂故不殆。○仕、輔政，汲古作事、作輔改，皆非，今依宋元本。殆音以，言與宵小並仕，雖忠必獲禍，退隱則免也。</p><h3 id="復之豫" tabindex="-1">復之豫 <a class="header-anchor" href="#復之豫" aria-label="Permalink to “復之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>卵與石鬬，糜碎無處。挈瓶之使，不為憂懼。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為卵，艮為石，震艮相反故曰鬬。坤為漿、為糜，震為瓶，艮手為挈，坎為憂懼。《左傳》：&quot;雖有挈瓶之知&quot;，註：汲者，喻小知。按：古汲用瓶。</p><h3 id="復之隨" tabindex="-1">復之隨 <a class="header-anchor" href="#復之隨" aria-label="Permalink to “復之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>五心六意，歧道多怪。非君本志，生我恨悔。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>巽卦數五，互大坎，為心意數六，震為道路、為君。</p><h3 id="復之蠱" tabindex="-1">復之蠱 <a class="header-anchor" href="#復之蠱" aria-label="Permalink to “復之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>雨雪載塗，東行破車，旅人無家。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>震為大塗、為東、為車，互大坎為雨雪，兌折故曰破車。震為商旅、為人，艮為家，在外故曰無家。○宋元本多&quot;利益諮嗟&quot;四字，依汲古。家與塗、車韻。</p><h3 id="復之臨" tabindex="-1">復之臨 <a class="header-anchor" href="#復之臨" aria-label="Permalink to “復之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>尚利壤義，月出平地。國亂天常，咎徵滅亡。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>伏巽為利，坤為義，兌毀故曰壞義。兌為月，坤為平地、為國、為滅亡。月出平地，用象神妙。○首句宋元本作&quot;尚刑懷義&quot;，依汲古。</p><h3 id="復之觀" tabindex="-1">復之觀 <a class="header-anchor" href="#復之觀" aria-label="Permalink to “復之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>東行破車，步入危家。衡門穿射，無以為主。賣袍續食，糟糠不飽。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>此用《復》象。震為東、為車，坤喪故曰破車。震為步、為射、為主、為袍、為糟糠，坤為門，坤虛故無以為主、故不飽。○危，汲古作範，從宋元本。</p><h3 id="復之噬嗑" tabindex="-1">復之噬嗑 <a class="header-anchor" href="#復之噬嗑" aria-label="Permalink to “復之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>逐禽出門，並失玉丸。往來井井，破甑缺益。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為逐、為出，艮為禽、為門。坎為失、為彈丸，震為玉，故曰玉丸。兌為井，初四伏正反兌，故曰往來井井。震為甑、為益，坎為破、為缺。○破甑，元本作破甕，汲古作甑破，依宋本。</p><h3 id="復之賁" tabindex="-1">復之賁 <a class="header-anchor" href="#復之賁" aria-label="Permalink to “復之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>孟春醴酒，使君壽考。南山多福，宜行賈市。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>稻梁雌雉，所至利喜。震為春、為長，故曰孟春。坎為酒，震為君，艮為壽考、為南山。伏巽為賈市、為稻梁。離為雌。○孟春，汲古作春孟，依宋元本。稻梁，汲古作秋梁，依宋元本。</p><h3 id="復之剝" tabindex="-1">復之剝 <a class="header-anchor" href="#復之剝" aria-label="Permalink to “復之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>持刃操肉，對酒不食。夫亡從軍，少子入獄，抱膝獨宿。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮手為持、為操、為刃，坤為軍，艮為夫，在上，故曰夫亡從軍。亡，往也。艮為少子，坤為宿。酒肉象均不詳。獄象膝象，疑皆指艮。</p><h3 id="復之復" tabindex="-1">復之復 <a class="header-anchor" href="#復之復" aria-label="Permalink to “復之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>周師伐紂，克於牧野。甲子平旦，天下悅喜。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震為周、為伐，坤為師、為惡，故為紂。坤為野、為養，故曰牧野。牧者，養也。乾初爻正值甲子，震為晨，故曰甲子平旦。坤為天下，震為悅喜。</p><h3 id="復之無妄" tabindex="-1">復之無妄 <a class="header-anchor" href="#復之無妄" aria-label="Permalink to “復之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>踦牛傷暑，不能成畝。草萊不鬬，年歲無有。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>京房以《無妄》為大旱之卦。艮為火故曰暑，為牛，巽下斷，故曰踦牛。坤為畝，二陰故不成畝。巽為草萊，乾為年歲，巽隕落故無年。</p><h3 id="復之大畜" tabindex="-1">復之大畜 <a class="header-anchor" href="#復之大畜" aria-label="Permalink to “復之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>南邦大國，鬼魅滿室。歡聲相逐，為我行賊。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>乾為南，艮為邦國，伏巽為鬼魅。艮為室，震為樂、為聲、為逐，伏巽為賊。《雜卦》巽伏也，伏故為鬼、為盜賊。○國，汲古作域，依宋元本。</p><h3 id="復之頤" tabindex="-1">復之頤 <a class="header-anchor" href="#復之頤" aria-label="Permalink to “復之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>噂噂所言，莫如我垣。歡樂堅固，可以長安。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>《毛傳》：&quot;噂，對語也&quot;。震為言，正覆震相對，故曰噂噂。艮為垣，正覆艮相對而艮為止，故曰莫如。如，往也。震為歡喜，艮為堅固、為安。○垣，宋元本訛恆，依汲古。</p><h3 id="復之大過" tabindex="-1">復之大過 <a class="header-anchor" href="#復之大過" aria-label="Permalink to “復之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>堯舜禹湯，四聖敦仁。允施德音，艮安無窮。旅人相望，未同朝鄉。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>乾為帝王、為聖、為仁，巽數四，故曰四聖。乾為德，兌為口，故曰德音。伏坤為民，艮為安、為望，震為商旅、為向，正反震相對。故曰旅人相望，曰未同朝鄉。鄉，向也。○鄉，汲古、宋本皆訛卿，依元本。下二句與上四句意不屬，疑為衍文。</p><h3 id="復之坎" tabindex="-1">復之坎 <a class="header-anchor" href="#復之坎" aria-label="Permalink to “復之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>桎梏拘獲，身入牢獄。髠刑受法，終不得釋。耳閉道塞，求事不得。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>坎為桎梏、為牢獄，伏巽為髠，坎陷故不得釋。坎為耳、為閉塞，艮為道路、為求。</p><h3 id="復之離" tabindex="-1">復之離 <a class="header-anchor" href="#復之離" aria-label="Permalink to “復之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>桀蹠並處，民困愁苦。行旅遲遲，留連齊魯。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>離為惡人，故曰桀。巽為盜，故曰蹠。伏坎為眾、為民、為愁苦，伏震為行旅，艮止故曰遲、曰留連。巽為齊，兌為魯。○首句元本作蹠桀並處，汲古作蹠並桀處，今依宋本。</p><h3 id="復之鹹" tabindex="-1">復之鹹 <a class="header-anchor" href="#復之鹹" aria-label="Permalink to “復之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>求雞獲雉，買鱉失魚。出人鈞敵，租得無餘。齊薑宋子，婚姻孔喜。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>艮為求，巽為雞、為魚，伏坤為文、為雉，艮為鱉。雞、雉、魚、鱉相等，故曰鈞敵。巽為利、為齊薑。艮為宋，少男少女相遇故曰婚姻。兌為悅，故曰孔喜。○敵，汲古作貨，依宋元本。餘，宋元作饒，依汲古。雉，宋元本作雛。</p><h3 id="復之恆" tabindex="-1">復之恆 <a class="header-anchor" href="#復之恆" aria-label="Permalink to “復之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>雨師駕駟，風伯吹雲。秦楚爭強，施不得行。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>互兌為雨，伏坤為師，震為馬，故曰雨師駕駟。巽為風，震為伯，伏坤為雲，兌口故曰吹雲。兌為秦，震為楚、為爭，乾健故曰爭強。獨斷雲：雨師，畢星；風伯，箕星也。</p><h3 id="復之遯" tabindex="-1">復之遯 <a class="header-anchor" href="#復之遯" aria-label="Permalink to “復之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>仲冬無秋，鳥鵲飢憂。困於米食，數驚鸇雕。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>通《臨》。復居子，故曰仲冬。兌為秋，坤虛故無秋，言仲冬之時，百物凋落也。艮為鳥鵲，坤為飢、為憂困，震為米，兌為食，艮為鸇雕。○無，汲古訛兼。鳥鵲飢憂，汲古作鳥散飲憂，依宋元本。</p><h3 id="復之大壯" tabindex="-1">復之大壯 <a class="header-anchor" href="#復之大壯" aria-label="Permalink to “復之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>三羝上山，俱至陰安。遂到南陽，見其芝香。兩崖相望，未同枕床。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>兌為羊，震數三，故曰三羝。艮為山，艮反故曰陰，言至山北也。乾為南、為陽，兌為見，伏巽為芝、為吞，伏艮為崖，兌卦數二，故曰兩崖，大壯上形似之。艮為枕、為床，艮伏故曰未同枕床。○見，汲古作完，同作有，均依宋元本。</p><h3 id="復之晉" tabindex="-1">復之晉 <a class="header-anchor" href="#復之晉" aria-label="Permalink to “復之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>飛之日南，還歸遼東。雌友相從，和鳴雍雍，解我胸舂。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>離為日、為南、為飛，艮東北，故曰遼東。坎雄離雌，坎為和，艮為胸，艮手為春。胸舂者，言胸臆上下不定，如舂米於胸中也。○之，宋元本作至。胸舂，宋本作逈舂，元本作逈春，均依汲古。</p><h3 id="復之明夷" tabindex="-1">復之明夷 <a class="header-anchor" href="#復之明夷" aria-label="Permalink to “復之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>堯飲舜舞，禹拜上酒。禮樂所豐，可以安處，保我淑女。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為帝，故曰堯舜禹。震為飲、為舞，坎為酒，坤為禮，震為樂。</p><h3 id="復之家人" tabindex="-1">復之家人 <a class="header-anchor" href="#復之家人" aria-label="Permalink to “復之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>大一置酒，樂正起舞。萬福攸同，可以安處，綏我齯齒。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>大一，即北辰。《史記天官書》：&quot;中宮天極星，其一明者大一，常居也&quot;，註：天神最尊貴者。離為星，故曰大一。坎為酒，伏震為樂、為舞、為萬福，兌為齒，卦有兩半兌形故曰齯齒。《爾雅》：&quot;黃發齯齒&quot;，註：齒隳更生細者。古單作兒。按：今詩正作兒齒。○大一，宋本、汲古俱作大乙，依元本。齯，汲古作見，依宋元本。</p><h3 id="復之睽" tabindex="-1">復之睽 <a class="header-anchor" href="#復之睽" aria-label="Permalink to “復之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>白馬騧騮，生乳不休。富我商人，得利饒優。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>坎為馬，兌西方，色白故曰白馬。伏艮為乳，馬乳可為酒。《漢書禮樂志》：&quot;以馬乳為酒&quot;，撞挏乃成。卦有兩半艮，故曰生乳不休。三四句疑亦用半象。○騧，汲古作騂，從宋元本。</p><h3 id="復之蹇" tabindex="-1">復之蹇 <a class="header-anchor" href="#復之蹇" aria-label="Permalink to “復之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>宛馬疾步，盲師坐御。目不見路，中止不到。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>宛，踠之省。《後漢書班固傳》：&quot;馬踠餘足&quot;，註：踠，屈也。又《說文》宛：屈草自覆也，是宛亦有屈意。宛馬疾步者，言馬足既屈而使之速行也。互坎為馬，坎為屈，故曰踠馬。坎為眾，為師，艮離目不全，故曰盲師。艮為坐，御本立，為今以盲師而坐御，故不見路而不到也。艮為路、為止。</p><h3 id="復之解" tabindex="-1">復之解 <a class="header-anchor" href="#復之解" aria-label="Permalink to “復之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>春桃萌生，萬物華榮。邦君所居，國樂無憂。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震為桃、為春、為萌、為生、為華榮、為君、為樂。</p><h3 id="復之損" tabindex="-1">復之損 <a class="header-anchor" href="#復之損" aria-label="Permalink to “復之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>把珠入口，蓄為玉寶。得吾所有，欣然嘉喜。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為珠玉，兌為口，坤為吾，震為喜，艮手為把。</p><h3 id="復之益" tabindex="-1">復之益 <a class="header-anchor" href="#復之益" aria-label="Permalink to “復之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>襦燒褲燔，羸剝饑寒，病虐凍攣。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>震為襦，巽為褲，艮為火，故曰燒燔。p s坤為羸，艮手為剝，坤為饑寒、為病虐、為凍。攣，系也。《說文》凡拘牽連繫者皆曰攣。○第三句病虐汲古作病癥，依宋元。攣，宋本作孿，依汲古。孿，《說文》雙生也，宋本非。</p><h3 id="復之夬" tabindex="-1">復之夬 <a class="header-anchor" href="#復之夬" aria-label="Permalink to “復之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>水沫沉浮，沮濕不居，為心疾憂。通《剝》。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>坤為水，一陽在上故曰水沫沉浮、曰沮濕。坤為心、為疾憂。</p><h3 id="復之姤" tabindex="-1">復之姤 <a class="header-anchor" href="#復之姤" aria-label="Permalink to “復之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>行如樂紂，雖禱不佑。命絕衰周，文君乏祀。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。坤為惡，故曰桀紂。震為行、為言，故曰禱。震為周、為君，巽為命，坤喪故命絕。坤為文，故曰文君，謂文王也。○佑，宋元本作祥，君作王，均依汲古。</p><h3 id="復之萃" tabindex="-1">復之萃 <a class="header-anchor" href="#復之萃" aria-label="Permalink to “復之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>蜱蜉戴盆，不能上山。腳摧跛蹶，損傷其顏。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>巽為蟲，故曰蜱蜉，艮形似覆盆，故曰戴盆。艮為山，震為足，震覆故曰腳摧、曰跛蹶。兌為損，艮為顏。○蜱蜉，汲古作蜉蝣，顏作頭，均依宋本。摧損，宋元本作推頓，均依汲古，元本註雲：蚍蜉有翼者曰蜱蜉。</p><h3 id="復之升" tabindex="-1">復之升 <a class="header-anchor" href="#復之升" aria-label="Permalink to “復之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>長子入獄，婦饋母哭。霜降愈甚，嚮晦伏法。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震為長子，互大坎為獄，巽為婦，坤為母，兌口為哭。坤為霜、為晦，坤死故曰伏法。○愈，汲古作旬，依宋元，疑旬字音訛為甚字。《周禮小司寇》：&quot;至於旬，乃弊之&quot;，而宋本作愈，疑原文為霜降逾旬。</p><h3 id="復之困" tabindex="-1">復之困 <a class="header-anchor" href="#復之困" aria-label="Permalink to “復之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>求犬得兔，請新遇故。雖不當路，逾吾舊舍。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>通《賁》。艮為犬、為求，震為兔，離為新，坎為故，艮為路、為舍。</p><h3 id="復之井" tabindex="-1">復之井 <a class="header-anchor" href="#復之井" aria-label="Permalink to “復之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>鳥鳴葭端，一呼三顛。動搖東西，危而不安。靈祝禱祉，疾病無患。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>對《噬嗑》。震為葭、為鳴呼，艮為鳥，坎數一，震數三，離為東，坎為西，坎險故危。震為言，故曰祝禱。坎為疾病，震喜故無患。全用對象，祇顛字用本卦《巽》。○動搖，宋元本作搖動，依汲古。祝，汲古作符，依宋元本。</p><h3 id="復之革" tabindex="-1">復之革 <a class="header-anchor" href="#復之革" aria-label="Permalink to “復之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>天厭禹德，命興湯國。祓社釁鼓，以除民疾。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。艮為天，震為王，故曰禹。坤為國、為水，故曰湯國。坤為社，震為鼓，坤為民，坎為疾，震樂故除疾。○第三句元本作祅社釁鼓，依宋本、汲古。</p><h3 id="復之鼎" tabindex="-1">復之鼎 <a class="header-anchor" href="#復之鼎" aria-label="Permalink to “復之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>陰霧作匿，不見白日。邪徑迷道，使君亂惑。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。坤為霧、為陰，坎為匿，故不見。離日，震為白，故曰白日。艮為徑、為道，坤為迷、為亂，震為君。○迷道，汲古作迷通，依宋元本。</p><h3 id="復之震" tabindex="-1">復之震 <a class="header-anchor" href="#復之震" aria-label="Permalink to “復之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>猿墮高木，不踒手足。握珠懷玉，還歸我室。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>艮為猿，震為木、為足，艮為手。踒，折也。艮在震上，故猿墮高木。震為珠玉、為歸，艮為握、為室。○踒，汲古作跛，依宋元本。</p><h3 id="復之艮" tabindex="-1">復之艮 <a class="header-anchor" href="#復之艮" aria-label="Permalink to “復之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>三驪負衡，南取芝香。秋蘭芬馥，盈滿篋筐，利我少薑。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>互震為馬，數三，艮為負、為衡，震為南，伏巽為芝、為香、為蘭、為芬馥，伏兌為秋，震為筐，巽為利、為薑。○第四句宋元本作盛滿匣匱，汲古作盈滿匣匱，依局本。</p><h3 id="復之漸" tabindex="-1">復之漸 <a class="header-anchor" href="#復之漸" aria-label="Permalink to “復之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>春生夏乳，羽毛成就。舉不失宜，君臣相好。盜走奔北，終無有悔。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>離為夏，艮為乳，伏震為春、為生、為羽毛、為君，艮為臣，坎為盜、為北，艮為終。○夏，汲古作孚，依宋元本。有悔，宋本作有晦，汲古作所悔，依元本。</p><h3 id="復之歸妹" tabindex="-1">復之歸妹 <a class="header-anchor" href="#復之歸妹" aria-label="Permalink to “復之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>東行破車，遠反失家。天命訖終，無所禱兇。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震為東、為行、為車，兌毀故破車。震為反，艮為家，艮伏故失家。伏巽為命，艮為天、為終，兌口為禱。○遠反失家，言反目遠處而無家也，與上句對文，汲古作還反室家，宋本作遠反室家，皆非，今依元本。</p><h3 id="復之豐" tabindex="-1">復之豐 <a class="header-anchor" href="#復之豐" aria-label="Permalink to “復之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>九雁列陣，雌獨不群。為罾所牽，死於庖人。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>震為雁，數九，故曰九雁。震為陣，巽為雌，在後，故曰不群。離為罾，兌折故死。震為人。</p><h3 id="復之旅" tabindex="-1">復之旅 <a class="header-anchor" href="#復之旅" aria-label="Permalink to “復之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>二人輦車，徙去其家。井沸釜鳴，不可以居。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>詳《剝》之《訟》。 ○徙，汲古訛從。下有艮火故井沸。</p><h3 id="復之巽" tabindex="-1">復之巽 <a class="header-anchor" href="#復之巽" aria-label="Permalink to “復之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>閉塞復通，與善相逢。甘棠之人，解我憂兇。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>通《震》。互坎為閉塞，震為通、為棠、為人，坎為憂，震通故解。《詩召南甘棠》篇、魯韓詩說皆謂召公聽訟棠下，茲曰解我憂兇是齊說，謂召公平反冤獄於其下也。</p><h3 id="復之兌" tabindex="-1">復之兌 <a class="header-anchor" href="#復之兌" aria-label="Permalink to “復之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>賦斂重數，政為民賊。杼柚空虛，去其家室。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《豐》。第四句汲古作&quot;家去其室&quot;，依宋元本。</p><h3 id="復之渙" tabindex="-1">復之渙 <a class="header-anchor" href="#復之渙" aria-label="Permalink to “復之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>怒非其願，貪妬腐鼠。而呼鵲鴟，自令失餌，致被殃患。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>震為怒，坎為妬，艮為鼠，巽腐，故曰腐鼠。震為呼，艮為鵲鴟，坎為失、為殃患，震為餌。○貪妬，宋本作貪垢，元本作含垢，茲依汲古。致被殃患，汲古作倒被災患，茲依宋元本。《莊子》：&quot;鴟得腐鼠，鵷雛過之，仰而視之曰：嚇&quot;。林用其意。</p><h3 id="復之節" tabindex="-1">復之節 <a class="header-anchor" href="#復之節" aria-label="Permalink to “復之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>簪短帶長，幽思苦窮。瘠蠡小，以病之癃。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為簪，兌折，故簪短。伏巽為帶、為長，坎為幽思、為瘠。，音陶，病也。○短，各本皆作跌，蠡作貌，依《恆》之《鹹》校改。蠡，音祼。《左傳桓六年》：&quot;謂其不疾瘯蠡也&quot;，註：疥病。小，宋本作小瘦，汲古作小疲，依元本。又苦窮各本皆作窮苦。病之隆，各本皆作疾病降，均依《恆》之《鹹》校。</p><h3 id="復之中孚" tabindex="-1">復之中孚 <a class="header-anchor" href="#復之中孚" aria-label="Permalink to “復之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>三人俱行，各別採桑。蘊其筐筥，留我嘉旅。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>得歸無咎，四月來處。震為人、為行，數三，故曰三人俱行。艮手為採，巽為桑，震為筐筥、為行旅、為歸，兌為月，數四，故曰四月。艮為處。○旅，汲古作侶，非，依宋元本。</p><h3 id="復之小過" tabindex="-1">復之小過 <a class="header-anchor" href="#復之小過" aria-label="Permalink to “復之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>逐鳩南飛，與喜相隨。並獲鹿子，多得利歸，雖憂不危。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為逐，艮為鳩，震為南、為飛、為喜、為子、為鹿、為歸、為利。</p><h3 id="復之既濟" tabindex="-1">復之既濟 <a class="header-anchor" href="#復之既濟" aria-label="Permalink to “復之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>驅羊南行，與禍相逢。狼驚吾馬，虎盜我子，悲恨自咎。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用《復》象。震為羊、為驅、為南、為行，坤為禍、為狼虎，震為馬、為驚、為子，伏巽為盜。坤為悲恨。</p><h3 id="復之未濟" tabindex="-1">復之未濟 <a class="header-anchor" href="#復之未濟" aria-label="Permalink to “復之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>東鄰西國，福喜同樂。出得隋珠，留獲和玉，俱利有息。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>離為東鄰，坎為西國。《既濟九五》爻詞正如此也，徒以先天象失傳，致解者皆誤。復震為福喜、為樂、為珠玉、為出，坤閉故曰留。○有息，宋元作有喜，失韻，依汲古。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
